package EX18.EX90;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.List;

public class Main {
    public static void main(String[] args) throws Exception {
        try (Connection conn = ConnectionFactory.getConnection();
             Statement st = conn.createStatement()) {
            st.execute("CREATE TABLE pedidos (" +
                    "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, " +
                    "cliente VARCHAR(120) NOT NULL, " +
                    "data_hora TIMESTAMP NOT NULL, " +
                    "total DECIMAL(12,2) NOT NULL)");
            st.execute("CREATE TABLE itens_pedido (" +
                    "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, " +
                    "pedido_id BIGINT NOT NULL REFERENCES pedidos(id), " +
                    "produto_id BIGINT NOT NULL, " +
                    "quantidade INT NOT NULL CHECK (quantidade > 0), " +
                    "preco_unitario DECIMAL(12,2) NOT NULL)");
        }

        VendaService service = new VendaService(new PedidoDAOImpl(), new ItemPedidoDAOImpl());

        long id = service.registrarVenda(new Pedido("Maria"), List.of(
                new ItemPedido(1, 2, new BigDecimal("50.00")),
                new ItemPedido(2, 1, new BigDecimal("30.00"))));
        System.out.println("Venda " + id + " gravada.");
        contar("Após venda válida");

        try {
            service.registrarVenda(new Pedido("João"), List.of(
                    new ItemPedido(1, 1, new BigDecimal("50.00")),
                    new ItemPedido(2, 0, new BigDecimal("30.00"))));
        } catch (RuntimeException e) {
            System.out.println("Erro: " + e.getMessage());
        }
        contar("Após venda inválida (deve continuar igual)");
    }

    private static void contar(String titulo) throws Exception {
        try (Connection conn = ConnectionFactory.getConnection();
             Statement st = conn.createStatement()) {
            ResultSet p = st.executeQuery("SELECT COUNT(*) FROM pedidos");
            p.next();
            int pedidos = p.getInt(1);
            ResultSet i = st.executeQuery("SELECT COUNT(*) FROM itens_pedido");
            i.next();
            System.out.println(titulo + " -> pedidos: " + pedidos + ", itens: " + i.getInt(1));
        }
    }
}
